18: /** 使用应用数据目录保存二进制对象，并通过临时文件与原子移动避免暴露半份内容。 */
19: @Component
20: @RequiredArgsConstructor
21: public class LocalBlobStore implements BlobStore {
22:     private static final int BUFFER_SIZE = 16 * 1024;
23:     private static final String OBJECT_PREFIX = "files/objects/";
24:     private static final String LEGACY_PREFIX = "records/attachments/";
25: 
26:     private final LocalDatabaseProperties databaseProperties;
27: 
28:     @Override
29:     public StoredBlob put(String objectId, InputStream content, long maximumBytes) {
30:         requireObjectId(objectId);
31:         if (content == null) throw new IllegalArgumentException("文件内容不能为空");
32:         if (maximumBytes < 1) throw new IllegalArgumentException("文件大小上限必须大于零");
33: 
34:         String storageKey = OBJECT_PREFIX + objectId.substring(0, 2) + "/" + objectId.substring(2, 4) + "/" + objectId;
35:         Path target = resolve(storageKey);
36:         Path stagingDirectory = dataRoot().resolve("files/staging");
37:         Path temporary = null;
38:         try {
39:             Files.createDirectories(target.getParent());
40:             Files.createDirectories(stagingDirectory);
41:             temporary = Files.createTempFile(stagingDirectory, ".upload-", ".tmp");
42:             MessageDigest digest = MessageDigest.getInstance("SHA-256");
43:             long size = copy(content, temporary, maximumBytes, digest);
44:             moveAtomically(temporary, target);
45:             temporary = null;
46:             return new StoredBlob(storageKey, size, HexFormat.of().formatHex(digest.digest()));
47:         } catch (IOException exception) {
48:             throw new IllegalStateException("本地文件写入失败", exception);
49:         } catch (NoSuchAlgorithmException exception) {
50:             throw new IllegalStateException("当前运行环境不支持 SHA-256", exception);
51:         } finally {
52:             deleteTemporary(temporary);
53:         }
54:     }
55: 
56:     @Override
57:     public InputStream open(String storageKey) {
58:         Path target = resolve(storageKey);
59:         if (Files.isSymbolicLink(target) || !Files.isRegularFile(target)) {
60:             throw new IllegalArgumentException("文件内容不存在");
61:         }
62:         try {
63:             return Files.newInputStream(target);
64:         } catch (IOException exception) {
65:             throw new IllegalStateException("本地文件读取失败", exception);
66:         }
67:     }
68: 
69:     @Override
70:     public void delete(String storageKey) {
71:         Path target = resolve(storageKey);
72:         if (Files.isSymbolicLink(target)) throw new IllegalArgumentException("文件对象不能是符号链接");
73:         try {
74:             Files.deleteIfExists(target);
75:         } catch (IOException exception) {
76:             throw new IllegalStateException("本地文件删除失败", exception);
77:         }
78:     }
79: 
80:     private long copy(InputStream source, Path target, long maximumBytes, MessageDigest digest) throws IOException {
81:         long total = 0;
82:         byte[] buffer = new byte[BUFFER_SIZE];
83:         try (OutputStream output = Files.newOutputStream(target)) {
84:             int read;
85:             while ((read = source.read(buffer)) != -1) {
86:                 total += read;
87:                 if (total > maximumBytes) throw new IllegalArgumentException("文件超过允许的大小上限");
88:                 output.write(buffer, 0, read);
89:                 digest.update(buffer, 0, read);
90:             }
91:         }
92:         return total;
93:     }
94: 
95:     private Path resolve(String storageKey) {
96:         if (storageKey == null
97:                 || (!storageKey.startsWith(OBJECT_PREFIX) && !storageKey.startsWith(LEGACY_PREFIX))) {
98:             throw new IllegalArgumentException("本地文件存储键非法");
99:         }
100:         Path root = dataRoot();
101:         Path resolved = root.resolve(storageKey).normalize();
102:         Path allowedRoot = storageKey.startsWith(OBJECT_PREFIX)
103:                 ? root.resolve("files/objects")
104:                 : root.resolve("records/attachments");
105:         if (!resolved.startsWith(allowedRoot)) throw new IllegalArgumentException("本地文件存储键越界");
106:         return resolved;
107:     }
108: 
109:     private Path dataRoot() {
110:         Path databasePath = databaseProperties.getPath().toAbsolutePath().normalize();
111:         Path parent = databasePath.getParent();
112:         if (parent == null) throw new IllegalStateException("SQLite 数据库路径必须包含父目录");
113:         return parent;
114:     }
115: 
116:     private void requireObjectId(String objectId) {
117:         if (objectId == null || !objectId.matches("[a-f0-9]{32}")) {
118:             throw new IllegalArgumentException("文件对象 ID 格式非法");
119:         }
120:     }
121: 
122:     private void moveAtomically(Path source, Path target) throws IOException {
123:         try {
124:             Files.move(source, target, StandardCopyOption.ATOMIC_MOVE);
125:         } catch (AtomicMoveNotSupportedException exception) {
126:             Files.move(source, target);
127:         }
128:     }
129: 
130:     private void deleteTemporary(Path temporary) {
131:         if (temporary == null) return;
132:         try {
133:             Files.deleteIfExists(temporary);
134:         } catch (IOException ignored) {
135:             // 主异常已包含写入失败原因；残留 staging 文件可由后续清理任务回收。
136:         }
137:     }
138: }

