130:                     if (event.isTerminal()) {
131:                         terminalDelivered.set(true);
132:                         return;
133:                     }
134:                 }
135:             } catch (IOException | IllegalStateException exception) {
136:                 // 前端关闭页面或网络断开时，SseEmitter 可能抛出这些异常。
137:                 log.debug("SSE 客户端已断开", exception);
138:             } catch (InterruptedException exception) {
139:                 // onCompletion 会中断 sender；恢复中断标记以便 finally 正常释放资源。
140:                 Thread.currentThread().interrupt();
141:             } finally {
142:                 // 只有非终态断开才取消生产者；正常终态不反向中断 AgentScope。
143:                 if (!terminalDelivered.get()) session.closeTransport();
144:                 emitter.complete();
145:             }
146:         });
